// Router and progressive motion
function render(scroll=true){
 const raw=location.hash.slice(1)||'/';const [path,query]=raw.split('?');const [route,id,tab]=path.split('/').filter(Boolean);
 if($('#modal').open)closeModal();observer?.disconnect();
 let html;
 if(!route)html=home();else if(route==='programas')html=programsPage(id);else if(route==='impacto')html=impact();else if(route==='blog')html=blog(id);else if(route==='nosotros')html=about();else if(route==='unete'){const p=new URLSearchParams(query).get('programa');if(p&&program(p))joinDraft.program=p;html=joinPage();}else if(route==='donar')html=donation();else if(route==='login')html=login(id);else if(route==='portal')html=portal(id,tab);else if(['privacidad','terminos','transparencia'].includes(route))html=legalPage(route);else html=notFound();
 $('#app').innerHTML=html;document.body.classList.toggle('is-portal',route==='portal'&&!!state.session);document.title=(route==='portal'?'Mi espacio':route?route.charAt(0).toUpperCase()+route.slice(1):'Personas en movimiento')+' · Fundación Impulsa Futuro';
 if(scroll){window.scrollTo({top:0,left:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;entry.target.classList.add('visible');const number=entry.target.dataset.count;if(number&&!reduced){const target=Number(number),start=performance.now();function animate(t){const fraction=Math.min(1,(t-start)/1000);entry.target.textContent=Math.round(target*(1-Math.pow(1-fraction,3))).toLocaleString('es-CO');if(fraction<1)requestAnimationFrame(animate);}requestAnimationFrame(animate);}observer.unobserve(entry.target);}),{threshold:0.12});
 $$('.reveal,[data-count]').forEach(el=>observer.observe(el));
}
window.addEventListener('hashchange',()=>render());
window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;$('#scroll-progress').style.width=(max>0?scrollY/max*100:0)+'%';$('.site-header')?.classList.toggle('scrolled',scrollY>20);},{passive:true});
render();
if(!storageAvailable)toast('El almacenamiento local no está disponible. Los cambios durarán solo esta sesión.');
